// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { ACCOUNTS, ADDED, CAPTIONS, START, STEP_SECONDS } from './script'

const ADDED_INDEX = ACCOUNTS.indexOf(ADDED)

const build: Build = ({ tl, q, qa, step, final, move, click, type, count, wait, cursorOut }) => {
  const roll = (account: number, slot: 1 | 2, at?: string) =>
    tl.to(
      qa(`strip-${account}`),
      { yPercent: (-100 / 3) * slot, duration: 0.45, stagger: 0.06, ease: 'back.out(1.6)' },
      at,
    )

  ACCOUNTS.forEach((_, index) => {
    if (index !== ADDED_INDEX) tl.set(qa(`strip-${index}`), { yPercent: -100 / 3 }, 0)
  })

  const start = tl.duration()
  step(0)
  move('label', { ax: 0.2, at: 0.2 })
  click('label')
  type('label-text', ADDED.label, { speed: 0.05 })

  step(1, '+=0.3')
  move('secret', { ax: 0.2 })
  click('secret')
  type('secret-text', ADDED.secret, { speed: 0.03 })
  move('add')
  click('add')
  tl.to([q('label-text'), q('secret-text')], { text: '', duration: 0.1 }, '<0.1')
  tl.fromTo(
    q(`account-${ADDED_INDEX}`),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'power2.out' },
    '<',
  )
  roll(ADDED_INDEX, 1, '>-0.05')
  const added = tl.duration()
  const tickedTo = START - Math.round(added - start)
  count('remain', tickedTo, { from: START, at: start, duration: added - start, ease: 'none' })

  step(2, '+=0.4')
  count('remain', 1, { from: tickedTo, duration: 2.2, ease: 'none' })
  tl.set(q('remain'), { text: String(STEP_SECONDS) }, '+=0.5')
  ACCOUNTS.forEach((_, index) => roll(index, 2, index === 0 ? '<' : '<0.1'))
  tl.fromTo(
    qa('account'),
    { borderColor: 'rgba(52,211,153,0.6)' },
    { borderColor: 'rgba(255,255,255,0.08)', duration: 0.8, immediateRender: false },
    '<',
  )

  step(3, '+=0.6')
  move(`copy-${ADDED_INDEX}`)
  click(`copy-${ADDED_INDEX}`)
  tl.to(q(`copy-icon-${ADDED_INDEX}`), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q(`done-${ADDED_INDEX}`),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

function Input({ d, placeholder }: { d: string; placeholder: string }) {
  return (
    <span
      data-d={d}
      className="relative flex h-7 items-center rounded-md border border-line-strong bg-canvas/80 px-2.5 text-[11px] text-ink"
    >
      <span data-d={`${d}-text`} className="peer font-mono text-[10.5px]" />
      <span className="absolute left-2.5 hidden text-muted peer-empty:block">{placeholder}</span>
    </span>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="TOTP adding a test account from its Base32 secret, then both codes rolling over when the 30-second window ends"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2">
          <p className="text-[10.5px] text-muted">
            Codes refresh in <span data-d="remain">{START}</span>s
          </p>
          <Input d="label" placeholder="Account label" />
          <Input d="secret" placeholder="Base32 secret" />
          <span
            data-d="add"
            className="flex h-7 w-fit items-center rounded-md bg-[var(--accent)] px-3 text-[11px] font-medium text-canvas"
          >
            Add account
          </span>
          <ul className="mt-1 flex flex-col gap-1.5">
            {ACCOUNTS.map((account, index) => (
              <li
                key={account.label}
                data-d={`account account-${index}`}
                className={`flex items-center justify-between rounded-lg border border-white/[0.08] px-3 py-1.5 ${
                  index === ADDED_INDEX ? 'opacity-0' : ''
                }`}
              >
                <div>
                  <p className="text-[11px] font-medium text-ink">{account.label}</p>
                  <p className="flex font-mono text-[17px] leading-6 tracking-[0.2em] text-ink">
                    {[...account.codes[0]].map((_, digit) => (
                      <span key={digit} className="h-6 overflow-hidden">
                        <span data-d={`strip-${index}`} className="flex flex-col">
                          <span>·</span>
                          <span>{account.codes[0][digit]}</span>
                          <span>{account.codes[1][digit]}</span>
                        </span>
                      </span>
                    ))}
                  </p>
                </div>
                <div className="flex flex-col items-end gap-0.5">
                  <span
                    data-d={`copy-${index}`}
                    className="flex h-6 items-center gap-1 rounded-md border border-line-strong px-2 text-[10px] text-ink-soft"
                  >
                    <span className="relative size-3">
                      <span data-d={`copy-icon-${index}`} className="absolute inset-0">
                        <CopyIcon className="size-3" />
                      </span>
                      <span
                        data-d={`done-${index}`}
                        className="absolute inset-0 text-[var(--accent)] opacity-0"
                      >
                        <CheckIcon className="size-3" />
                      </span>
                    </span>
                    Copy
                  </span>
                  <span className="px-2 text-[10px] text-muted">Delete</span>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
